std::string decoded_text;
std::shared_ptr<Node> current_node = root;
char buffer = 0;
int bit_pos = 0;
int bits_read = 0;
while (bits_read < encoded_length) {
    if (infile.eof()) {
        break;
    }
    if (bit_pos == 0) {
        infile.read(&buffer, sizeof(char));
    }
    int bit = (buffer >> (7 - bit_pos)) & 1;
    if (bit == 0) {
        current_node = current_node->left;
    } else {
        current_node = current_node->right;
    }
    bit_pos++;
    bits_read++;
    if (current_node->left == nullptr && current_node->right == nullptr) {
        decoded_text += current_node->character;
        current_node = root;
        bit_pos = 0;
    }
    if (bit_pos == 8) {
        bit_pos = 0;
    }
}
return decoded_text;

